{
  "name": "A4 Layout to Word",
  "description": "A drag-and-drop A4 layout tool that exports directly to Microsoft Word (.docx) format."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum BlockType {
  IMAGE = 'IMAGE',
  TEXT_ROW = 'TEXT_ROW',
  TITLE = 'TITLE'
}

export interface Block {
  id: string;
  type: BlockType;
  content: string; // Image URL or Main Text
  subContent?: string; // Secondary Text (for text rows)
  height?: number; // Optional visual height override for images
}

import { 
  Document, 
  Packer, 
  Paragraph, 
  TextRun, 
  ImageRun, 
  Table, 
  TableRow, 
  TableCell, 
  WidthType,
  AlignmentType,
  BorderStyle
} from "docx";
import { saveAs } from "file-saver";
import { Block, BlockType } from "../types";

// Helper to convert base64/url to ArrayBuffer for docx
const urlToArrayBuffer = async (url: string): Promise<ArrayBuffer> => {
  const response = await fetch(url);
  const blob = await response.blob();
  return await blob.arrayBuffer();
};

export const exportToDocx = async (blocks: Block[], margin: number) => {
  // 1. Prepare Content Generation
  const docChildren: (Paragraph | Table)[] = [];

  // We need to process blocks. 
  // Specifically, if we have consecutive images, we want to try and put them side-by-side 
  // to mimic the CSS flex layout (50% width).

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];

    if (block.type === BlockType.TITLE) {
      docChildren.push(
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 200, after: 200 },
          children: [
            new TextRun({
              text: block.content,
              bold: true,
              size: 32, // 16pt
            }),
          ],
        })
      );
    } 

    else if (block.type === BlockType.TEXT_ROW) {
      // Create a 2-column table with invisible borders
      const row = new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        borders: {
            top: { style: BorderStyle.NIL, size: 0, color: "auto" },
            bottom: { style: BorderStyle.DASHED, size: 1, color: "AAAAAA" }, // Dashed bottom like web
            left: { style: BorderStyle.NIL, size: 0, color: "auto" },
            right: { style: BorderStyle.NIL, size: 0, color: "auto" },
            insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
            insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
        },
        rows: [
          new TableRow({
            children: [
              new TableCell({
                width: { size: 40, type: WidthType.PERCENTAGE },
                children: [
                  new Paragraph({
                    children: [
                      new TextRun({
                        text: block.content,
                        bold: true,
                        size: 24, // 12pt
                      })
                    ]
                  })
                ]
              }),
              new TableCell({
                width: { size: 60, type: WidthType.PERCENTAGE },
                children: [
                   new Paragraph({
                    alignment: AlignmentType.RIGHT,
                    children: [
                      new TextRun({
                        text: block.subContent || "",
                        color: "666666",
                        size: 20, // 10pt
                      })
                    ]
                  })
                ]
              })
            ]
          })
        ]
      });

      docChildren.push(row);
      // Add a small spacer paragraph
      docChildren.push(new Paragraph({ spacing: { after: 100 } }));
    } 

    else if (block.type === BlockType.IMAGE) {
      // Check if next block is also an image for 2-column layout
      const nextBlock = blocks[i + 1];
      const isNextImage = nextBlock && nextBlock.type === BlockType.IMAGE;

      const imgBuffer1 = await urlToArrayBuffer(block.content);

      // Calculate dimensions. A4 is roughly 210mm wide. 
      // Margins are 10mm each side => ~190mm usable.
      // 190mm = ~718 pixels (at 96 DPI).
      // Docx uses EMU or pixels.

      if (isNextImage) {
        // Two images side by side
        const imgBuffer2 = await urlToArrayBuffer(nextBlock.content);

        const table = new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
                top: { style: BorderStyle.NIL, size: 0, color: "auto" },
                bottom: { style: BorderStyle.NIL, size: 0, color: "auto" },
                left: { style: BorderStyle.NIL, size: 0, color: "auto" },
                right: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
            },
            rows: [
                new TableRow({
                    children: [
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    children: [
                                        new ImageRun({
                                            data: imgBuffer1,
                                            transformation: { width: 300, height: 200 }, // Fixed aspect ratio approx
                                        })
                                    ]
                                })
                            ]
                        }),
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    children: [
                                        new ImageRun({
                                            data: imgBuffer2,
                                            transformation: { width: 300, height: 200 },
                                        })
                                    ]
                                })
                            ]
                        })
                    ]
                })
            ]
        });

        docChildren.push(table);
        // Skip next block since we processed it
        i++; 
      } else {
        // Single Image (Full Width relative to container, usually 50% in CSS but full row here if alone? 
        // The original CSS puts images in 50% width slots. If one is alone, it stays 50% width left aligned or takes full?
        // CSS: .img-wrapper { width: calc(50% - 5px) }. It's a flex container. 
        // So a single image takes up half the page width.

        docChildren.push(
            new Paragraph({
                children: [
                    new ImageRun({
                        data: imgBuffer1,
                        transformation: { width: 300, height: 200 }, 
                    })
                ]
            })
        );
      }

      // Add margin bottom
      docChildren.push(new Paragraph({ spacing: { after: margin * 10 } })); 
    }
  }

  // 2. Create Document
  const doc = new Document({
    sections: [
      {
        properties: {
            page: {
                margin: {
                    top: 567, // 10mm in TWIPs (approx)
                    bottom: 567,
                    left: 567,
                    right: 567
                }
            }
        },
        children: docChildren,
      },
    ],
  });

  // 3. Generate and Save
  const blob = await Packer.toBlob(doc);
  saveAs(blob, `export_${new Date().toISOString().slice(0,10)}.docx`);
};

import React from 'react';
import { Block, BlockType } from '../types';
import { X } from 'lucide-react';

interface BlockRendererProps {
  block: Block;
  onUpdate: (id: string, updates: Partial<Block>) => void;
  onRemove: (id: string) => void;
  isDragging?: boolean;
}

export const BlockRenderer: React.FC<BlockRendererProps> = ({ block, onUpdate, onRemove, isDragging }) => {
  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onRemove(block.id);
  };

  const preventDrag = (e: React.MouseEvent) => {
    e.stopPropagation();
  };

  if (block.type === BlockType.TITLE) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-400 min-h-[50px] flex items-center justify-center hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <input 
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={preventDrag}
          className="text-center text-2xl font-extrabold bg-transparent w-full outline-none focus:border-b focus:border-blue-500"
          placeholder="Input Title"
        />
      </div>
    );
  }

  if (block.type === BlockType.TEXT_ROW) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-400 px-4 py-2 flex items-baseline gap-4 min-h-[40px] hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <input 
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={preventDrag}
          className="text-lg font-bold text-gray-800 bg-transparent min-w-[50px] outline-none focus:border-b focus:border-blue-500"
          placeholder="Name"
        />
        <input 
          value={block.subContent || ''}
          onChange={(e) => onUpdate(block.id, { subContent: e.target.value })}
          onMouseDown={preventDrag}
          className="flex-grow text-sm text-gray-600 bg-transparent outline-none focus:border-b focus:border-blue-500 text-right"
          placeholder="Note"
        />
      </div>
    );
  }

  if (block.type === BlockType.IMAGE) {
    return (
      <div 
        className={`group relative w-[calc(50%-5px)] border border-dashed border-gray-300 min-h-[60px] overflow-hidden bg-white hover:border-blue-400 ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute top-1 right-1 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <img 
            src={block.content} 
            alt="Uploaded" 
            className="w-full h-auto object-contain pointer-events-none" 
        />
      </div>
    );
  }

  return null;
};

import React, { useState, useRef, useEffect } from 'react';
import { Plus, Printer, FileDown, Type, Image as ImageIcon, Heading } from 'lucide-react';
import { Block, BlockType } from './types';
import { BlockRenderer } from './components/BlockRenderer';
import { exportToDocx } from './services/docxService';

// Helper to generate IDs
const generateId = () => Math.random().toString(36).substr(2, 9);

function App() {
  const [blocks, setBlocks] = useState<Block[]>([]);
  const [margin, setMargin] = useState(5);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Drag and Drop State
  const [draggedBlockIndex, setDraggedBlockIndex] = useState<number | null>(null);

  // --- Actions ---

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newBlocks: Block[] = [];
      Array.from(e.target.files).forEach((file) => {
        if (file.type.startsWith('image/')) {
          const url = URL.createObjectURL(file);
          newBlocks.push({
            id: generateId(),
            type: BlockType.IMAGE,
            content: url
          });
        }
      });
      setBlocks(prev => [...prev, ...newBlocks]);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const addTextRow = () => {
    setBlocks(prev => [...prev, {
      id: generateId(),
      type: BlockType.TEXT_ROW,
      content: 'New Name',
      subContent: 'Details here'
    }]);
  };

  const addTitleRow = () => {
    setBlocks(prev => [...prev, {
      id: generateId(),
      type: BlockType.TITLE,
      content: 'Document Title'
    }]);
  };

  const updateBlock = (id: string, updates: Partial<Block>) => {
    setBlocks(prev => prev.map(b => b.id === id ? { ...b, ...updates } : b));
  };

  const removeBlock = (id: string) => {
    setBlocks(prev => prev.filter(b => b.id !== id));
  };

  const handleExportDocx = async () => {
    try {
      await exportToDocx(blocks, margin);
    } catch (error) {
      console.error("Export failed", error);
      alert("Failed to export Docx. Please check console.");
    }
  };

  // --- Drag & Drop Logic (Native API for Mixed Grid Layouts) ---

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedBlockIndex(index);
    e.dataTransfer.effectAllowed = "move";
    // Optional: Set drag image ghost
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault(); // Necessary to allow dropping
    if (draggedBlockIndex === null || draggedBlockIndex === index) return;

    // Reorder array
    const newBlocks = [...blocks];
    const draggedItem = newBlocks[draggedBlockIndex];
    newBlocks.splice(draggedBlockIndex, 1);
    newBlocks.splice(index, 0, draggedItem);

    setBlocks(newBlocks);
    setDraggedBlockIndex(index);
  };

  const handleDragEnd = () => {
    setDraggedBlockIndex(null);
  };

  // --- Layout Pagination Simulation ---
  // In this React version, we render a continuous stream for editing, 
  // but wrap it in an A4 container to give the visual cue.
  // We heavily rely on CSS Flexbox to handle the wrapping logic (2 images vs 1 text).

  return (
    <div className="min-h-screen bg-[#525659] flex flex-col items-center py-5 font-sans">

      {/* --- Toolbar --- */}
      <div className="bg-white p-4 rounded-lg shadow-lg mb-6 sticky top-4 z-50 flex flex-wrap gap-4 items-center max-w-[95vw]">

        <div className="flex items-center gap-2 pr-4 border-r border-gray-200">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded font-medium transition-colors"
          >
            <ImageIcon size={18} /> Add Image
          </button>
          <button 
            onClick={addTextRow}
            className="flex items-center gap-2 bg-[#32666f] hover:bg-[#264d54] text-white px-4 py-2 rounded font-medium transition-colors"
          >
            <Type size={18} /> Add Text
          </button>
          <button 
            onClick={addTitleRow}
            className="flex items-center gap-2 bg-[#32666f] hover:bg-[#264d54] text-white px-4 py-2 rounded font-medium transition-colors"
          >
            <Heading size={18} /> Add Title
          </button>
        </div>

        <div className="flex items-center gap-2 pr-4 border-r border-gray-200">
          <label className="text-sm font-semibold text-gray-700">Margin:</label>
          <input 
            type="range" 
            min="0" 
            max="50" 
            value={margin} 
            onChange={(e) => setMargin(Number(e.target.value))}
            className="w-24 cursor-pointer"
          />
          <span className="text-sm text-gray-600 w-12">{margin}px</span>
        </div>

        <div className="flex gap-2">
            <button 
                onClick={() => window.print()}
                className="flex items-center gap-2 bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded font-medium transition-colors"
            >
                <Printer size={18} /> Print / PDF
            </button>
            <button 
                onClick={handleExportDocx}
                className="flex items-center gap-2 bg-blue-800 hover:bg-blue-900 text-white px-4 py-2 rounded font-medium transition-colors border border-blue-900"
            >
                <FileDown size={18} /> Export Word
            </button>
        </div>

        <input 
          type="file" 
          ref={fileInputRef} 
          hidden 
          multiple 
          accept="image/*" 
          onChange={handleImageUpload} 
        />
      </div>

      {/* --- Page Container --- */}
      {/* 
        We use a single container that emulates A4 width. 
        In a real "Page" view, we would calculate height splitting, 
        but for this requirement, a continuous flow with CSS columns logic is smoother for editing.
      */}
      <div id="page-container" className="flex flex-col items-center w-full">
        <div 
            className="a4-page bg-white p-[10mm] box-border flex flex-wrap content-start gap-[10px] shadow-xl relative"
            style={{ 
                width: '210mm', 
                minHeight: '297mm', // Minimum one page
                // We use flex wrap logic: Images are calc(50% - 5px). Text is 100%.
                // This mimics the original CSS perfectly.
            }}
        >
            {blocks.length === 0 && (
                <div className="w-full h-64 flex flex-col items-center justify-center text-gray-400 border-2 border-dashed border-gray-200 rounded">
                    <p>Drag & drop images here or use the toolbar to add content.</p>
                </div>
            )}

            {blocks.map((block, index) => (
                <div
                    key={block.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, index)}
                    onDragOver={(e) => handleDragOver(e, index)}
                    onDragEnd={handleDragEnd}
                    className={`
                        ${block.type === BlockType.IMAGE ? 'w-[calc(50%-5px)]' : 'w-full'}
                        transition-all duration-200 ease-in-out cursor-move
                        ${draggedBlockIndex === index ? 'opacity-40 scale-95' : 'opacity-100'}
                    `}
                    style={{ marginBottom: `${margin}px` }}
                >
                    <BlockRenderer 
                        block={block} 
                        onUpdate={updateBlock} 
                        onRemove={removeBlock}
                        isDragging={draggedBlockIndex === index}
                    />
                </div>
            ))}
        </div>
      </div>

      <div className="mt-8 text-gray-400 text-sm no-print">
        Tip: Drag items to reorder. Changes are reflected in Print & Word Export.
      </div>
    </div>
  );
}

export default App;

