                        isDragging={draggedBlockIndex === index}
                    />
                </div>
            ))}
        </div>
      </div>

      <div className="mt-8 text-gray-400 text-sm no-print">
        Tip: Drag items to reorder. Changes are reflected in Print & Word Export.
      </div>
    </div>
  );
}

