import { 
  Document, 
  Packer, 
  Paragraph, 
  TextRun, 
  ImageRun, 
  Table, 
  TableRow, 
  TableCell, 
  WidthType,
  AlignmentType,
  BorderStyle
} from "docx";
import FileSaver from "file-saver";
import { Block, BlockType } from "../types";

// Helper to convert base64/url to ArrayBuffer for docx
const urlToArrayBuffer = async (url: string): Promise<ArrayBuffer> => {
  const response = await fetch(url);
  const blob = await response.blob();
  return await blob.arrayBuffer();
};

export const exportToDocx = async (blocks: Block[], margin: number) => {
  // 1. Prepare Content Generation
  const docChildren: (Paragraph | Table)[] = [];

  // We need to process blocks. 
  // Specifically, if we have consecutive images, we want to try and put them side-by-side 
  // to mimic the CSS flex layout (50% width).

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];

    if (block.type === BlockType.TITLE) {
      docChildren.push(
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 200, after: 200 },
          children: [
            new TextRun({
              text: block.content,
              bold: true,
              size: 32, // 16pt
            }),
          ],
        })
      );
    } 

    else if (block.type === BlockType.TEXT_ROW) {
      // Create a 2-column table with invisible borders
      const row = new Table({
        width: { size: 100, type: WidthType.PERCENTAGE },
        borders: {
            top: { style: BorderStyle.NIL, size: 0, color: "auto" },
            bottom: { style: BorderStyle.DASHED, size: 1, color: "AAAAAA" }, // Dashed bottom like web
            left: { style: BorderStyle.NIL, size: 0, color: "auto" },
            right: { style: BorderStyle.NIL, size: 0, color: "auto" },
            insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
            insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
        },
        rows: [
          new TableRow({
            children: [
              new TableCell({
                width: { size: 40, type: WidthType.PERCENTAGE },
                children: [
                  new Paragraph({
                    children: [
                      new TextRun({
                        text: block.content,
                        bold: true,
                        size: 24, // 12pt
                      })
                    ]
                  })
                ]
              }),
              new TableCell({
                width: { size: 60, type: WidthType.PERCENTAGE },
                children: [
                   new Paragraph({
                    alignment: AlignmentType.RIGHT,
                    children: [
                      new TextRun({
                        text: block.subContent || "",
                        color: "666666",
                        size: 20, // 10pt
                      })
                    ]
                  })
                ]
              })
            ]
          })
        ]
      });

      docChildren.push(row);
      // Add a small spacer paragraph
      docChildren.push(new Paragraph({ spacing: { after: 100 } }));
    } 

    else if (block.type === BlockType.IMAGE) {
      // Check if next block is also an image for 2-column layout
      const nextBlock = blocks[i + 1];
      const isNextImage = nextBlock && nextBlock.type === BlockType.IMAGE;

      const imgBuffer1 = await urlToArrayBuffer(block.content);

      // Calculate dimensions. A4 is roughly 210mm wide. 
      // Margins are 10mm each side => ~190mm usable.
      // 190mm = ~718 pixels (at 96 DPI).
      // Docx uses EMU or pixels.

      if (isNextImage) {
        // Two images side by side
        const imgBuffer2 = await urlToArrayBuffer(nextBlock.content);

        const table = new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
                top: { style: BorderStyle.NIL, size: 0, color: "auto" },
                bottom: { style: BorderStyle.NIL, size: 0, color: "auto" },
                left: { style: BorderStyle.NIL, size: 0, color: "auto" },
                right: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
            },
            rows: [
                new TableRow({
                    children: [
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    children: [
                                        new ImageRun({
                                            data: imgBuffer1,
                                            transformation: { width: 300, height: 200 }, // Fixed aspect ratio approx
                                        })
                                    ]
                                })
                            ]
                        }),
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    children: [
                                        new ImageRun({
                                            data: imgBuffer2,
                                            transformation: { width: 300, height: 200 },
                                        })
                                    ]
                                })
                            ]
                        })
                    ]
                })
            ]
        });

        docChildren.push(table);
        // Skip next block since we processed it
        i++; 
      } else {
        // Single Image (Full Width relative to container, usually 50% in CSS but full row here if alone? 
        // The original CSS puts images in 50% width slots. If one is alone, it stays 50% width left aligned or takes full?
        // CSS: .img-wrapper { width: calc(50% - 5px) }. It's a flex container. 
        // So a single image takes up half the page width.

        docChildren.push(
            new Paragraph({
                children: [
                    new ImageRun({
                        data: imgBuffer1,
                        transformation: { width: 300, height: 200 }, 
                    })
                ]
            })
        );
      }

      // Add margin bottom
      docChildren.push(new Paragraph({ spacing: { after: margin * 10 } })); 
    }
  }

  // 2. Create Document
  const doc = new Document({
    sections: [
      {
        properties: {
            page: {
                margin: {
                    top: 567, // 10mm in TWIPs (approx)
                    bottom: 567,
                    left: 567,
                    right: 567
                }
            }
        },
        children: docChildren,
      },
    ],
  });

  // 3. Generate and Save
  const blob = await Packer.toBlob(doc);
  FileSaver.saveAs(blob, `export_${new Date().toISOString().slice(0,10)}.docx`);
};

import React, { useRef, useState, useEffect } from 'react';
import { Block, BlockType } from '../types';
import { X, GripHorizontal } from 'lucide-react';

interface BlockRendererProps {
  block: Block;
  onUpdate: (id: string, updates: Partial<Block>) => void;
  onRemove: (id: string) => void;
  isDragging?: boolean;
}

export const BlockRenderer: React.FC<BlockRendererProps> = ({ block, onUpdate, onRemove, isDragging }) => {
  const [imgHeight, setImgHeight] = useState<number | undefined>(block.height);
  const containerRef = useRef<HTMLDivElement>(null);

  // Sync state with props if props change externally
  useEffect(() => {
    setImgHeight(block.height);
  }, [block.height]);

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onRemove(block.id);
  };

  const preventDrag = (e: React.MouseEvent) => {
    e.stopPropagation();
  };

  // --- Resize/Crop Logic ---
  const handleMouseDownResize = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const startY = e.clientY;
    // If no height set yet, use current rendered height
    const startHeight = imgHeight || containerRef.current?.clientHeight || 200;

    const onMouseMove = (moveEvent: MouseEvent) => {
      const delta = moveEvent.clientY - startY;
      const newHeight = Math.max(50, startHeight + delta); // Minimum 50px
      setImgHeight(newHeight);
    };

    const onMouseUp = (upEvent: MouseEvent) => {
      const delta = upEvent.clientY - startY;
      const finalHeight = Math.max(50, startHeight + delta);
      // Persist to parent state
      onUpdate(block.id, { height: finalHeight });

      document.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('mouseup', onMouseUp);
    };

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  };

  if (block.type === BlockType.TITLE) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-300 min-h-[50px] flex items-center justify-center hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <input 
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={preventDrag}
          className="text-center text-2xl font-extrabold text-black bg-transparent w-full outline-none focus:border-b focus:border-blue-500 placeholder-gray-400"
          placeholder="Document Title"
        />
      </div>
    );
  }

  if (block.type === BlockType.TEXT_ROW) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-300 px-4 py-2 flex items-baseline gap-4 min-h-[40px] hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <input 
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={preventDrag}
          className="text-lg font-bold text-gray-900 bg-transparent min-w-[50px] outline-none focus:border-b focus:border-blue-500"
          placeholder="Name"
        />
        <input 
          value={block.subContent || ''}
          onChange={(e) => onUpdate(block.id, { subContent: e.target.value })}
          onMouseDown={preventDrag}
          className="flex-grow text-sm text-gray-600 bg-transparent outline-none focus:border-b focus:border-blue-500 text-right"
          placeholder="Note"
        />
      </div>
    );
  }

  if (block.type === BlockType.IMAGE) {
    return (
      <div 
        ref={containerRef}
        className={`group relative w-full border border-dashed border-gray-300 bg-white hover:border-blue-400 overflow-hidden select-none ${isDragging ? 'opacity-50' : ''}`}
        style={{ height: imgHeight ? `${imgHeight}px` : 'auto' }}
      >
        <button 
            onClick={handleDelete}
            className="absolute top-1 right-1 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-20"
        >
          <X size={14} />
        </button>

        {/* Image: Top aligned, covers width, hides bottom if cropped */}
        <img 
            src={block.content} 
            alt="Uploaded" 
            className="w-full object-cover object-top pointer-events-none block"
            style={{ 
              height: imgHeight ? '100%' : 'auto',
              minHeight: '100%' 
            }}
        />

        {/* Resize Handle */}
        <div 
          onMouseDown={handleMouseDownResize}
          className="absolute bottom-0 left-0 w-full h-5 bg-black/10 hover:bg-blue-500/50 cursor-ns-resize flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <GripHorizontal size={16} className="text-white drop-shadow-md" />
        </div>
      </div>
    );
  }

  return null;
};

