// Helper to convert base64/url to ArrayBuffer for docx
// Now supports cropping via Canvas if a cropHeight is provided
const processImage = async (url: string, cropHeight?: number): Promise<ArrayBuffer> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = url;

    img.onload = () => {
      // Logic: 
      // The web editor displays images at approx 354px width (Half of A4 210mm - padding).
      // We need to calculate the crop ratio based on that to match "what you see".
      const REFERENCE_DISPLAY_WIDTH = 354; 

      let finalBufferPromise: Promise<ArrayBuffer>;

      if (cropHeight) {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        // Calculate the aspect ratio the user sees on screen
        // Visible Ratio = RenderedWidth / RenderedHeight
        // We want to apply this ratio to the full resolution image

        // 1. Determine how much of the intrinsic image height should be kept.
        // Scale = IntrinsicWidth / ReferenceDisplayWidth
        // TargetIntrinsicHeight = cropHeight * Scale
        const scale = img.naturalWidth / REFERENCE_DISPLAY_WIDTH;
        const targetIntrinsicHeight = cropHeight * scale;

        canvas.width = img.naturalWidth;
        canvas.height = Math.min(targetIntrinsicHeight, img.naturalHeight);

        if (ctx) {
          // Draw image top-aligned
          ctx.drawImage(img, 0, 0);

          finalBufferPromise = new Promise((res) => {
             canvas.toBlob((blob) => {
                if (blob) res(blob.arrayBuffer());
                else res(new ArrayBuffer(0));
             }, 'image/png');
          });
        } else {
           // Fallback if canvas fails
           finalBufferPromise = fetch(url).then(r => r.arrayBuffer());
        }
      } else {
        // No crop, just fetch original
        finalBufferPromise = fetch(url).then(r => r.arrayBuffer());
      }

      resolve(finalBufferPromise);
    };

    img.onerror = () => {
      // Fallback
      fetch(url).then(r => r.arrayBuffer()).then(resolve).catch(reject);
    };
  });
};

