      // Process image (crop if needed)
      const imgBuffer1 = await processImage(block.content, block.height);

      // Docx Layout Logic
      // Single Image: We display it full width in the half-width cell? 
      // No, in the Web App, single images are still 50% width.
      // So in Docx, a single image should be in a table with an empty second cell, or just a paragraph with appropriate indentation?
      // To match the grid layout of the web app perfectly, we should probably always use a table row for images.

      // If we have 2 images, we put them in one row.
      // If we have 1 image, we check if the previous one was an image? No, the loop handles blocks linearly.
      // We will pair them up manually here.

      if (isNextImage) {
        const imgBuffer2 = await processImage(nextBlock.content, nextBlock.height);

        const table = new Table({
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
