                                            transformation: { width: 300, height: block.height ? (300 * block.height / 354) : 200 }, 
                                        })
                                    ]
                                })
                            ]
                        }),
                        new TableCell({ width: { size: 50, type: WidthType.PERCENTAGE }, children: [] })
                    ]
                })
            ]
