import React, { useRef, useState, useEffect } from 'react';
import { Block, BlockType } from '../types';
import { X, GripHorizontal } from 'lucide-react';

interface BlockRendererProps {
  block: Block;
  onUpdate: (id: string, updates: Partial<Block>) => void;
  onRemove: (id: string) => void;
  isDragging?: boolean;
}

export const BlockRenderer: React.FC<BlockRendererProps> = ({ block, onUpdate, onRemove, isDragging }) => {
  const [imgHeight, setImgHeight] = useState<number | undefined>(block.height);
  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);

  // Sync state with props if props change externally
  useEffect(() => {
    setImgHeight(block.height);
  }, [block.height]);

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onRemove(block.id);
  };

  const preventDrag = (e: React.MouseEvent) => {
    e.stopPropagation();
  };

  // --- Resize/Crop Logic ---
  const handleMouseDownResize = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const startY = e.clientY;
    // Current visual height of the container
    const startHeight = containerRef.current?.clientHeight || 0;

    // The full height of the image if it wasn't cropped
    // We can get this from the img element itself, which is rendered full width
    const fullImageHeight = imgRef.current?.getBoundingClientRect().height || 1000;

    const onMouseMove = (moveEvent: MouseEvent) => {
      const delta = moveEvent.clientY - startY;
      // Calculate new height
      let newHeight = startHeight + delta;

      // Constraints:
      // Min: 50px
      // Max: fullImageHeight (cannot drag container larger than the image inside)
      newHeight = Math.max(50, Math.min(newHeight, fullImageHeight));

      setImgHeight(newHeight);
    };

    const onMouseUp = (upEvent: MouseEvent) => {
        // Calculate final height similar to mouse move to ensure consistency
        const delta = upEvent.clientY - startY;
        let finalHeight = startHeight + delta;
        const fullImageHeight = imgRef.current?.getBoundingClientRect().height || 1000;
        finalHeight = Math.max(50, Math.min(finalHeight, fullImageHeight));

        onUpdate(block.id, { height: finalHeight });

        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
    };

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  };

  if (block.type === BlockType.TITLE) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-300 min-h-[50px] flex items-center justify-center hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <input 
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={preventDrag}
          className="text-center text-2xl font-extrabold text-black bg-transparent w-full outline-none focus:border-b focus:border-blue-500 placeholder-gray-400"
          placeholder="文档标题"
        />
      </div>
    );
  }

  if (block.type === BlockType.TEXT_ROW) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-300 px-4 py-2 flex items-center min-h-[40px] hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <textarea 
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={preventDrag}
          rows={1}
          className="w-full text-lg text-black bg-transparent outline-none focus:border-b focus:border-blue-500 resize-none overflow-hidden"
          placeholder="在此输入文本..."
          style={{ height: 'auto' }}
          onInput={(e) => {
            // Auto-grow textarea
            (e.target as HTMLTextAreaElement).style.height = 'auto';
            (e.target as HTMLTextAreaElement).style.height = (e.target as HTMLTextAreaElement).scrollHeight + 'px';
          }}
        />
      </div>
    );
  }

  if (block.type === BlockType.IMAGE) {
    return (
      <div 
        ref={containerRef}
        className={`group relative w-full border border-dashed border-gray-300 bg-white hover:border-blue-400 overflow-hidden select-none ${isDragging ? 'opacity-50' : ''}`}
        // If height is undefined, use 'auto' to show full image. If set, use pixel value to crop.
        style={{ height: imgHeight ? `${imgHeight}px` : 'auto' }}
      >
        <button 
            onClick={handleDelete}
            className="absolute top-1 right-1 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-20"
        >
          <X size={14} />
        </button>

        {/* Image: Width 100%, Height Auto to maintain aspect ratio. 
            The container simply cuts off the bottom if height < natural height. 
        */}
        <img 
            ref={imgRef}
            src={block.content} 
            alt="Uploaded" 
            className="w-full h-auto block pointer-events-none"
        />

        {/* Resize Handle */}
        <div 
          onMouseDown={handleMouseDownResize}
          className="absolute bottom-0 left-0 w-full h-5 bg-black/10 hover:bg-blue-500/50 cursor-ns-resize flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <GripHorizontal size={16} className="text-white drop-shadow-md" />
        </div>
      </div>
    );
  }

  return null;
};

import React, { useState, useRef } from 'react';
import { FileDown, Type, Image as ImageIcon, Heading } from 'lucide-react';
import { Block, BlockType } from './types';
import { BlockRenderer } from './components/BlockRenderer';
import { exportToDocx } from './services/docxService';

// Helper to generate IDs
const generateId = () => Math.random().toString(36).substr(2, 9);

function App() {
  const [blocks, setBlocks] = useState<Block[]>([]);
  const [margin, setMargin] = useState(5);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Drag and Drop State
  const [draggedBlockIndex, setDraggedBlockIndex] = useState<number | null>(null);

  // --- Actions ---

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newBlocks: Block[] = [];
      Array.from(e.target.files).forEach((item) => {
        const file = item as File;
        if (file.type.startsWith('image/')) {
          const url = URL.createObjectURL(file);
          newBlocks.push({
            id: generateId(),
            type: BlockType.IMAGE,
            content: url,
            // height: undefined, // Let it be auto (natural aspect ratio)
          });
        }
      });
      setBlocks(prev => [...prev, ...newBlocks]);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const addTextRow = () => {
    setBlocks(prev => [...prev, {
      id: generateId(),
      type: BlockType.TEXT_ROW,
      content: '新文本',
    }]);
  };

  const addTitleRow = () => {
    setBlocks(prev => [...prev, {
      id: generateId(),
      type: BlockType.TITLE,
      content: '文档标题'
    }]);
  };

  const updateBlock = (id: string, updates: Partial<Block>) => {
    setBlocks(prev => prev.map(b => b.id === id ? { ...b, ...updates } : b));
  };

  const removeBlock = (id: string) => {
    setBlocks(prev => prev.filter(b => b.id !== id));
  };

  const handleExportDocx = async () => {
    try {
      const filename = window.prompt("请输入文件名 (不需要后缀)", "导出文档");
      if (filename) {
        await exportToDocx(blocks, margin, filename);
      }
    } catch (error) {
      console.error("Export failed", error);
      alert("导出失败，请检查控制台。");
    }
  };

  // --- Drag & Drop Logic ---

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedBlockIndex(index);
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault(); 
    if (draggedBlockIndex === null || draggedBlockIndex === index) return;

    const newBlocks = [...blocks];
    const draggedItem = newBlocks[draggedBlockIndex];
    newBlocks.splice(draggedBlockIndex, 1);
    newBlocks.splice(index, 0, draggedItem);

    setBlocks(newBlocks);
    setDraggedBlockIndex(index);
  };

  const handleDragEnd = () => {
    setDraggedBlockIndex(null);
  };

  return (
    <div className="min-h-screen bg-[#333333] flex flex-col items-center py-5 font-sans">

      {/* --- Toolbar --- */}
      <div className="bg-white px-6 py-3 rounded-lg shadow-xl mb-8 sticky top-4 z-50 flex flex-wrap gap-6 items-center border border-gray-200">

        <div className="flex items-center gap-3 pr-6 border-r border-gray-200">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="flex items-center gap-2 bg-black hover:bg-gray-800 text-white px-4 py-2 rounded-md text-sm font-medium transition-colors shadow-sm"
          >
            <ImageIcon size={16} /> 添加图片
          </button>
          <button 
            onClick={addTextRow}
            className="flex items-center gap-2 bg-white hover:bg-gray-50 text-black border border-gray-300 px-4 py-2 rounded-md text-sm font-medium transition-colors shadow-sm"
          >
            <Type size={16} /> 添加文本
          </button>
          <button 
            onClick={addTitleRow}
            className="flex items-center gap-2 bg-white hover:bg-gray-50 text-black border border-gray-300 px-4 py-2 rounded-md text-sm font-medium transition-colors shadow-sm"
          >
            <Heading size={16} /> 添加标题
          </button>
        </div>

        <div className="flex items-center gap-3 pr-6 border-r border-gray-200">
          <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">间距</label>
          <input 
            type="range" 
            min="0" 
            max="50" 
            value={margin} 
            onChange={(e) => setMargin(Number(e.target.value))}
            className="w-24 cursor-pointer accent-black"
          />
          <span className="text-sm font-mono text-gray-600 w-8 text-right">{margin}</span>
        </div>

        <div className="flex gap-3">
            <button 
                onClick={handleExportDocx}
                className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-md text-sm font-medium transition-colors shadow-sm"
            >
                <FileDown size={16} /> 导出文档
            </button>
        </div>

        <input 
          type="file" 
          ref={fileInputRef} 
          hidden 
          multiple 
          accept="image/*" 
          onChange={handleImageUpload} 
        />
      </div>

      {/* --- Page Container --- */}
      <div id="page-container" className="flex flex-col items-center w-full overflow-y-auto pb-10">
        <div 
            className="a4-page bg-white p-[10mm] box-border flex flex-wrap content-start gap-[10px] shadow-2xl relative transition-all"
            style={{ 
                width: '210mm', 
                minHeight: '297mm', // A4 Height
            }}
        >
            {blocks.length === 0 && (
                <div className="absolute inset-0 m-[10mm] flex flex-col items-center justify-center text-gray-300 border-2 border-dashed border-gray-100 rounded-lg pointer-events-none">
                    <p className="font-medium">画布为空</p>
                    <p className="text-sm">请从工具栏添加图片或文本</p>
                </div>
            )}

            {blocks.map((block, index) => (
                <div
                    key={block.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, index)}
                    onDragOver={(e) => handleDragOver(e, index)}
                    onDragEnd={handleDragEnd}
                    className={`
                        ${block.type === BlockType.IMAGE ? 'w-[calc(50%-5px)]' : 'w-full'}
                        transition-transform duration-200 ease-out cursor-move relative
                        ${draggedBlockIndex === index ? 'opacity-30 scale-95' : 'opacity-100'}
                    `}
                    style={{ marginBottom: `${margin}px` }}
                >
                    <BlockRenderer 
                        block={block} 
                        onUpdate={updateBlock} 
                        onRemove={removeBlock}
                        isDragging={draggedBlockIndex === index}
                    />
                </div>
            ))}
        </div>
      </div>
    </div>
  );
}

export default App;

import { 
  Document, 
  Packer, 
  Paragraph, 
  TextRun, 
  ImageRun, 
  Table, 
  TableRow, 
  TableCell, 
  WidthType,
  AlignmentType,
  BorderStyle
} from "docx";
import FileSaver from "file-saver";
import { Block, BlockType } from "../types";

// Helper to determine image type from blob type
const getImageType = (mimeType: string): "png" | "jpg" | "gif" | "bmp" => {
    if (mimeType.includes("png")) return "png";
    if (mimeType.includes("gif")) return "gif";
    if (mimeType.includes("bmp")) return "bmp";
    return "jpg";
};

// Helper to convert base64/url to ArrayBuffer for docx
// Now supports cropping via Canvas if a cropHeight is provided
const processImage = async (url: string, cropHeight?: number): Promise<{ data: ArrayBuffer, type: "png" | "jpg" | "gif" | "bmp" }> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = url;

    const resolveOriginal = () => {
        fetch(url)
            .then(r => r.blob())
            .then(async blob => {
                resolve({ 
                    data: await blob.arrayBuffer(), 
                    type: getImageType(blob.type) 
                });
            })
            .catch(reject);
    };

    img.onload = () => {
      // Logic: 
      // The web editor displays images at approx 354px width (Half of A4 210mm - padding).
      // We need to calculate the crop ratio based on that to match "what you see".
      const REFERENCE_DISPLAY_WIDTH = 354; 

      if (cropHeight) {
        // Calculate expected height if image was full width (scale logic)
        // If cropHeight >= expectedHeight, we don't need to crop (or user expanded it fully)
        // Actually, if cropHeight is present, we should trust it, but we need to map 
        // screen pixels to image pixels.

        const scale = img.naturalWidth / REFERENCE_DISPLAY_WIDTH;
        const targetIntrinsicHeight = cropHeight * scale;

        // If target height covers the whole image, just return original
        if (targetIntrinsicHeight >= img.naturalHeight - 1) { // epsilon
             resolveOriginal();
             return;
        }

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        canvas.width = img.naturalWidth;
        canvas.height = targetIntrinsicHeight;

        if (ctx) {
          // Draw image top-aligned. The bottom part is cut off.
          ctx.drawImage(img, 0, 0);

          canvas.toBlob((blob) => {
             if (blob) {
                blob.arrayBuffer().then(buffer => {
                    resolve({ data: buffer, type: "png" });
                });
             }
             else {
                resolve({ data: new ArrayBuffer(0), type: "png" });
             }
          }, 'image/png');
        } else {
           resolveOriginal();
        }
      } else {
        resolveOriginal();
      }
    };

    img.onerror = () => {
      resolveOriginal();
    };
  });
};

export const exportToDocx = async (blocks: Block[], margin: number, filename: string) => {
  const docChildren: (Paragraph | Table)[] = [];

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];

    if (block.type === BlockType.TITLE) {
      docChildren.push(
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 200, after: 200 },
          children: [
            new TextRun({
              text: block.content,
              bold: true,
              size: 32, // 16pt
              color: "000000"
            }),
          ],
        })
      );
    } 

    else if (block.type === BlockType.TEXT_ROW) {
      // Changed to simple paragraph, left aligned
      docChildren.push(
        new Paragraph({
            alignment: AlignmentType.LEFT,
            spacing: { before: 100, after: 100 },
            children: [
                new TextRun({
                    text: block.content,
                    size: 24, // 12pt
                    color: "000000"
                })
            ]
        })
      );
    } 

    else if (block.type === BlockType.IMAGE) {
      const nextBlock = blocks[i + 1];
      const isNextImage = nextBlock && nextBlock.type === BlockType.IMAGE;

      const img1 = await processImage(block.content, block.height);

      if (isNextImage) {
        const img2 = await processImage(nextBlock.content, nextBlock.height);

        const table = new Table({
            // REMOVED AlignmentType.CENTER from Table to ensure it flows from left
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
                top: { style: BorderStyle.NIL, size: 0, color: "auto" },
                bottom: { style: BorderStyle.NIL, size: 0, color: "auto" },
                left: { style: BorderStyle.NIL, size: 0, color: "auto" },
                right: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
            },
            rows: [
                new TableRow({
                    children: [
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    alignment: AlignmentType.CENTER, // Center image in cell
                                    children: [
                                        new ImageRun({
                                            data: img1.data,
                                            transformation: { width: 300, height: block.height ? (300 * block.height / 354) : (300 * (await getImageAspectRatio(block.content))) }, 
                                            type: img1.type,
                                        })
                                    ]
                                })
                            ]
                        }),
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    alignment: AlignmentType.CENTER, // Center image in cell
                                    children: [
                                        new ImageRun({
                                            data: img2.data,
                                            transformation: { width: 300, height: nextBlock.height ? (300 * nextBlock.height / 354) : (300 * (await getImageAspectRatio(nextBlock.content))) },
                                            type: img2.type,
                                        })
                                    ]
                                })
                            ]
                        })
                    ]
                })
            ]
        });
        docChildren.push(table);
        i++; // Skip next
      } else {
        // Single Image
        const table = new Table({
            // REMOVED AlignmentType.CENTER from Table
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
                top: { style: BorderStyle.NIL, size: 0, color: "auto" },
                bottom: { style: BorderStyle.NIL, size: 0, color: "auto" },
                left: { style: BorderStyle.NIL, size: 0, color: "auto" },
                right: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
            },
            rows: [
                new TableRow({
                    children: [
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    alignment: AlignmentType.CENTER, // Center image inside the LEFT cell
                                    children: [
                                        new ImageRun({
                                            data: img1.data,
                                            transformation: { width: 300, height: block.height ? (300 * block.height / 354) : (300 * (await getImageAspectRatio(block.content))) }, 
                                            type: img1.type,
                                        })
                                    ]
                                })
                            ]
                        }),
                        new TableCell({ width: { size: 50, type: WidthType.PERCENTAGE }, children: [] })
                    ]
                })
            ]
        });
        docChildren.push(table);
      }

      docChildren.push(new Paragraph({ spacing: { after: margin * 10 } })); 
    }
  }

  const doc = new Document({
    sections: [
      {
        properties: {
            page: {
                margin: {
                    top: 567,
                    bottom: 567,
                    left: 567,
                    right: 567
                }
            }
        },
        children: docChildren,
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  FileSaver.saveAs(blob, `${filename}.docx`);
};

// Helper to get Aspect Ratio (H/W) for Docx scaling
const getImageAspectRatio = (url: string): Promise<number> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = url;
        img.onload = () => {
            resolve(img.naturalHeight / img.naturalWidth);
        };
        img.onerror = () => resolve(1);
    });
};

