import React, { useRef, useState, useEffect } from 'react';
import { Block, BlockType } from '../types';
import { X, GripHorizontal } from 'lucide-react';

interface BlockRendererProps {
  block: Block;
  onUpdate: (id: string, updates: Partial<Block>) => void;
  onRemove: (id: string) => void;
  isDragging?: boolean;
  onEditStart?: () => void;
  onEditEnd?: () => void;
}

export const BlockRenderer: React.FC<BlockRendererProps> = ({ 
  block, 
  onUpdate, 
  onRemove, 
  isDragging,
  onEditStart,
  onEditEnd 
}) => {
  const [imgHeight, setImgHeight] = useState<number | undefined>(block.height);
  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);

  // Sync state with props if props change externally
  useEffect(() => {
    setImgHeight(block.height);
  }, [block.height]);

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onRemove(block.id);
  };

  // When user clicks input, notify parent to disable dragging
  const handleInputMouseDown = (e: React.MouseEvent) => {
    e.stopPropagation();
    onEditStart?.();
  };

  // When input loses focus, re-enable dragging
  const handleInputBlur = () => {
    onEditEnd?.();
  };

  // --- Resize/Crop Logic ---
  const handleMouseDownResize = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const startY = e.clientY;
    const startHeight = containerRef.current?.clientHeight || 0;
    const fullImageHeight = imgRef.current?.getBoundingClientRect().height || 1000;

    const onMouseMove = (moveEvent: MouseEvent) => {
      const delta = moveEvent.clientY - startY;
      let newHeight = startHeight + delta;
      newHeight = Math.max(50, Math.min(newHeight, fullImageHeight));
      setImgHeight(newHeight);
    };

    const onMouseUp = (upEvent: MouseEvent) => {
        const delta = upEvent.clientY - startY;
        let finalHeight = startHeight + delta;
        const fullImageHeight = imgRef.current?.getBoundingClientRect().height || 1000;
        finalHeight = Math.max(50, Math.min(finalHeight, fullImageHeight));

        onUpdate(block.id, { height: finalHeight });
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
    };

    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  };

  if (block.type === BlockType.TITLE) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-400 min-h-[50px] flex items-center justify-center hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>
        <input 
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={handleInputMouseDown}
          onBlur={handleInputBlur}
          className="text-center text-3xl font-extrabold text-[#111] bg-transparent outline-none border-b border-transparent focus:border-blue-500 focus:bg-white transition-colors py-2 max-w-full"
          placeholder="文档标题"
          style={{ width: `${Math.max((block.content.length || 0) + 1, 4)}em` }}
        />
      </div>
    );
  }

  if (block.type === BlockType.TEXT_ROW) {
    return (
      <div 
        className={`group relative w-full border border-dashed border-gray-400 px-4 py-1 flex items-baseline gap-4 min-h-[40px] hover:bg-gray-50 transition-colors ${isDragging ? 'opacity-50' : ''}`}
      >
        <button 
            onClick={handleDelete}
            className="absolute -top-2 -right-2 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <X size={14} />
        </button>

        {/* Main Text Input: Auto width based on content */}
        <input
          value={block.content}
          onChange={(e) => onUpdate(block.id, { content: e.target.value })}
          onMouseDown={handleInputMouseDown}
          onBlur={handleInputBlur}
          className="text-xl font-bold text-[#333] bg-transparent outline-none border-b border-dashed border-transparent focus:border-blue-500 focus:bg-white"
          placeholder="姓名/标题"
          style={{ width: `${Math.max((block.content.length || 0) + 1, 4)}em` }} 
        />

        {/* Sub Text Input: Auto width, removed flex-grow so user can click empty space to drag */}
        <input
          value={block.subContent || ''}
          onChange={(e) => onUpdate(block.id, { subContent: e.target.value })}
          onMouseDown={handleInputMouseDown}
          onBlur={handleInputBlur}
          className="text-sm text-[#666] bg-transparent outline-none border-b border-dashed border-transparent focus:border-blue-500 focus:bg-white"
          placeholder="备注信息"
          style={{ width: `${Math.max((block.subContent?.length || 0) + 1, 4)}em` }} 
        />
      </div>
    );
  }

  if (block.type === BlockType.IMAGE) {
    return (
      <div 
        ref={containerRef}
        className={`group relative w-full border border-dashed border-gray-300 bg-white hover:border-blue-400 overflow-hidden select-none ${isDragging ? 'opacity-50' : ''}`}
        style={{ height: imgHeight ? `${imgHeight}px` : 'auto' }}
      >
        <button 
            onClick={handleDelete}
            className="absolute top-1 right-1 w-6 h-6 bg-red-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-20"
        >
          <X size={14} />
        </button>

        <img 
            ref={imgRef}
            src={block.content} 
            alt="Uploaded" 
            className="w-full h-auto block pointer-events-none"
        />

        <div 
          onMouseDown={handleMouseDownResize}
          className="absolute bottom-0 left-0 w-full h-5 bg-black/10 hover:bg-blue-500/50 cursor-ns-resize flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity z-10"
        >
          <GripHorizontal size={16} className="text-white drop-shadow-md" />
        </div>
      </div>
    );
  }

  return null;
};

import { 
  Document, 
  Packer, 
  Paragraph, 
  TextRun, 
  ImageRun, 
  Table, 
  TableRow, 
  TableCell, 
  WidthType,
  AlignmentType,
  BorderStyle,
  TableLayoutType
} from "docx";
import FileSaver from "file-saver";
import { Block, BlockType } from "../types";

// Helper to determine image type from blob type
const getImageType = (mimeType: string): "png" | "jpg" | "gif" | "bmp" => {
    if (mimeType.includes("png")) return "png";
    if (mimeType.includes("gif")) return "gif";
    if (mimeType.includes("bmp")) return "bmp";
    return "jpg";
};

// Helper to convert base64/url to ArrayBuffer for docx
// Now supports cropping via Canvas if a cropHeight is provided
const processImage = async (url: string, cropHeight?: number): Promise<{ data: ArrayBuffer, type: "png" | "jpg" | "gif" | "bmp" }> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = url;

    const resolveOriginal = () => {
        fetch(url)
            .then(r => r.blob())
            .then(async blob => {
                resolve({ 
                    data: await blob.arrayBuffer(), 
                    type: getImageType(blob.type) 
                });
            })
            .catch(reject);
    };

    img.onload = () => {
      // Logic: 
      // The web editor displays images at approx 354px width (Half of A4 210mm - padding).
      // We need to calculate the crop ratio based on that to match "what you see".
      const REFERENCE_DISPLAY_WIDTH = 354; 

      if (cropHeight) {
        // Calculate expected height if image was full width (scale logic)
        // If cropHeight >= expectedHeight, we don't need to crop (or user expanded it fully)
        // Actually, if cropHeight is present, we should trust it, but we need to map 
        // screen pixels to image pixels.

        const scale = img.naturalWidth / REFERENCE_DISPLAY_WIDTH;
        const targetIntrinsicHeight = cropHeight * scale;

        // If target height covers the whole image, just return original
        if (targetIntrinsicHeight >= img.naturalHeight - 1) { // epsilon
             resolveOriginal();
             return;
        }

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        canvas.width = img.naturalWidth;
        canvas.height = targetIntrinsicHeight;

        if (ctx) {
          // Draw image top-aligned. The bottom part is cut off.
          ctx.drawImage(img, 0, 0);

          canvas.toBlob((blob) => {
             if (blob) {
                blob.arrayBuffer().then(buffer => {
                    resolve({ data: buffer, type: "png" });
                });
             }
             else {
                resolve({ data: new ArrayBuffer(0), type: "png" });
             }
          }, 'image/png');
        } else {
           resolveOriginal();
        }
      } else {
        resolveOriginal();
      }
    };

    img.onerror = () => {
      resolveOriginal();
    };
  });
};

export const exportToDocx = async (blocks: Block[], margin: number, filename: string) => {
  const docChildren: (Paragraph | Table)[] = [];

  for (let i = 0; i < blocks.length; i++) {
    const block = blocks[i];

    if (block.type === BlockType.TITLE) {
      docChildren.push(
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 200, after: 200 },
          children: [
            new TextRun({
              text: block.content,
              bold: true,
              size: 32, // 16pt - rough conversion
              color: "000000"
            }),
          ],
        })
      );
    } 

    else if (block.type === BlockType.TEXT_ROW) {
      // Export Text Row with Main content and Sub content
      const runs = [
          new TextRun({
              text: block.content,
              bold: true,
              size: 24, // 12pt
              color: "333333"
          })
      ];

      if (block.subContent) {
          // Add a tab or space separator
          runs.push(new TextRun({ text: "    " })); 
          runs.push(new TextRun({
              text: block.subContent,
              size: 20, // 10pt
              color: "666666"
          }));
      }

      docChildren.push(
        new Paragraph({
            alignment: AlignmentType.LEFT,
            spacing: { before: 100, after: 100 },
            children: runs
        })
      );
    } 

    else if (block.type === BlockType.IMAGE) {
      const nextBlock = blocks[i + 1];
      const isNextImage = nextBlock && nextBlock.type === BlockType.IMAGE;

      const img1 = await processImage(block.content, block.height);

      if (isNextImage) {
        const img2 = await processImage(nextBlock.content, nextBlock.height);

        const table = new Table({
            layout: TableLayoutType.FIXED, // Force columns to stay 50/50
            alignment: AlignmentType.CENTER, 
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
                top: { style: BorderStyle.NIL, size: 0, color: "auto" },
                bottom: { style: BorderStyle.NIL, size: 0, color: "auto" },
                left: { style: BorderStyle.NIL, size: 0, color: "auto" },
                right: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
            },
            rows: [
                new TableRow({
                    children: [
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    alignment: AlignmentType.CENTER, 
                                    children: [
                                        new ImageRun({
                                            data: img1.data,
                                            transformation: { width: 300, height: block.height ? (300 * block.height / 354) : (300 * (await getImageAspectRatio(block.content))) }, 
                                            type: img1.type,
                                        })
                                    ]
                                })
                            ]
                        }),
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    alignment: AlignmentType.CENTER, 
                                    children: [
                                        new ImageRun({
                                            data: img2.data,
                                            transformation: { width: 300, height: nextBlock.height ? (300 * nextBlock.height / 354) : (300 * (await getImageAspectRatio(nextBlock.content))) },
                                            type: img2.type,
                                        })
                                    ]
                                })
                            ]
                        })
                    ]
                })
            ]
        });
        docChildren.push(table);
        i++; // Skip next
      } else {
        // Single Image
        const table = new Table({
            layout: TableLayoutType.FIXED, // Force columns to stay 50/50
            alignment: AlignmentType.CENTER,
            width: { size: 100, type: WidthType.PERCENTAGE },
            borders: {
                top: { style: BorderStyle.NIL, size: 0, color: "auto" },
                bottom: { style: BorderStyle.NIL, size: 0, color: "auto" },
                left: { style: BorderStyle.NIL, size: 0, color: "auto" },
                right: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideVertical: { style: BorderStyle.NIL, size: 0, color: "auto" },
                insideHorizontal: { style: BorderStyle.NIL, size: 0, color: "auto" },
            },
            rows: [
                new TableRow({
                    children: [
                        new TableCell({
                            width: { size: 50, type: WidthType.PERCENTAGE },
                            children: [
                                new Paragraph({
                                    alignment: AlignmentType.CENTER, 
                                    children: [
                                        new ImageRun({
                                            data: img1.data,
                                            transformation: { width: 300, height: block.height ? (300 * block.height / 354) : (300 * (await getImageAspectRatio(block.content))) }, 
                                            type: img1.type,
                                        })
                                    ]
                                })
                            ]
                        }),
                        new TableCell({ 
                            width: { size: 50, type: WidthType.PERCENTAGE }, 
                            children: [new Paragraph({})] // Insert empty paragraph to prevent cell collapse
                        })
                    ]
                })
            ]
        });
        docChildren.push(table);
      }

      docChildren.push(new Paragraph({ spacing: { after: margin * 10 } })); 
    }
  }

  const doc = new Document({
    sections: [
      {
        properties: {
            page: {
                margin: {
                    top: 567,
                    bottom: 567,
                    left: 567,
                    right: 567
                }
            }
        },
        children: docChildren,
      },
    ],
  });

  const blob = await Packer.toBlob(doc);
  FileSaver.saveAs(blob, `${filename}.docx`);
};

// Helper to get Aspect Ratio (H/W) for Docx scaling
const getImageAspectRatio = (url: string): Promise<number> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = url;
        img.onload = () => {
            resolve(img.naturalHeight / img.naturalWidth);
        };
        img.onerror = () => resolve(1);
    });
};

