      {/* --- Modern Floating Toolbar --- */}
      <div className="sticky top-4 z-50 mb-8 mx-auto">
        <div className="flex items-center gap-1.5 p-2 bg-white/95 backdrop-blur-md rounded-2xl shadow-2xl border border-gray-100/50">

